                                let candidate_number =
                                    match candidate.get("type").and_then(Value::as_str) {
                                        Some("movie") => 1,
                                        Some("show") => 2,
                                        Some("season") => 3,
                                        Some("episode") => 4,
                                        _ => 0,
                                    };
                                candidate_number == number
