        // own 400 to a PUT with no `url`.
        if request.method == "PUT"
            && tail.len() == 1
            && matches!(
                tail[0],
                "poster" | "art" | "thumb" | "banner" | "theme" | "clearLogo"
            )
            && query.get("url").map_or(true, |url| url.is_empty())
        {
            return Response::error(400, "rex: bad request");
        }
