                // oracle's `global_views`), which a deleted history row does not lower;
                // only a `viewedAt` key counts the surviving history rows.
                let dated = query
                    .keys()
                    .any(|name| matches!(name.as_str(), "viewedAt>" | "viewedAt<" | "viewedAt"));
